import base64, textwrap
script = r'''
import csv
import sys
from collections import defaultdict

cpg_path, length_path, answer_path, details_path = sys.argv[1:5]

lengths = {}
with open(length_path, newline='', encoding='utf-8-sig') as handle:
    reader = csv.DictReader(handle)
    required = {'Chromosome', 'Length'}
    missing = required - set(reader.fieldnames or [])
    if missing:
        raise SystemExit(f\"Length file missing columns: {sorted(missing)}\")
    for row in reader:
        chrom = str(row['Chromosome']).strip()
        if not chrom:
            continue
        lengths[chrom] = int(float(str(row['Length']).strip()))

sites_by_chrom = defaultdict(set)
with open(cpg_path, newline='', encoding='utf-8-sig') as handle:
    reader = csv.DictReader(handle)
    required = {'Chromosome', 'StartPosition', 'EndPosition', 'MethylationPercentage'}
    missing = required - set(reader.fieldnames or [])
    if missing:
        raise SystemExit(f\"CpG file missing columns: {sorted(missing)}\")
    for row in reader:
        methyl = float(str(row['MethylationPercentage']).strip())
        if methyl > 90.0 or methyl < 10.0:
            chrom = str(row['Chromosome']).strip()
            start = str(row['StartPosition']).strip()
            end = str(row['EndPosition']).strip()
            sites_by_chrom[chrom].add((start, end))

densities = []
rows = []
def chrom_key(label):
    try:
        return (0, int(label))
    except ValueError:
        return (1, label)

for chrom in sorted(sites_by_chrom, key=chrom_key):
    count = len(sites_by_chrom[chrom])
    if count == 0:
        continue
    if chrom not in lengths:
        raise SystemExit(f\"No length for chromosome {chrom}\")
    length = lengths[chrom]
    density = count / length
    densities.append(density)
    rows.append((chrom, count, length, density))

if not densities:
    raise SystemExit('No chromosomes have filtered CpGs')

mean_density = sum(densities) / len(densities)
with open(answer_path, 'w', encoding='utf-8') as out:
    out.write(format(mean_density, '.17g') + '\\n')
with open(details_path, 'w', encoding='utf-8', newline='') as out:
    writer = csv.writer(out, delimiter='\\t')
    writer.writerow(['Chromosome', 'FilteredUniqueCpGs', 'Length', 'Density'])
    for chrom, count, length, density in rows:
        writer.writerow([chrom, count, length, format(density, '.17g')])
    writer.writerow(['MEAN', '', len(densities), format(mean_density, '.17g')])
'''
print(base64.b64encode(script.encode()).decode())
PY"

